# Google Calendar API - Node.js Skill

## Setup & Installation

```bash
npm install googleapis
```

## Authentication with OAuth2

Use pre-existing tokens (access_token + refresh_token) from a tokens.json file:

```javascript
const { google } = require('googleapis');

// Load credentials and tokens
const credentials = require('./auth/calendar/credentials.json');
const tokens = require('./auth/calendar/tokens.json');

const { client_id, client_secret } = credentials.installed;
const account = tokens.accounts[tokens.defaultAccount];

const oauth2Client = new google.auth.OAuth2(client_id, client_secret);
oauth2Client.setCredentials({
  access_token: account.access_token,
  refresh_token: account.refresh_token,
});

const calendar = google.calendar({ version: 'v3', auth: oauth2Client });
```

## List Events (Check Busy Times)

```javascript
// List events for a specific date range
const res = await calendar.events.list({
  calendarId: 'primary',
  timeMin: '2026-01-06T00:00:00Z',  // ISO 8601 format
  timeMax: '2026-01-09T23:59:59Z',
  singleEvents: true,
  orderBy: 'startTime',
});

const events = res.data.items;
events.forEach(event => {
  console.log(`${event.summary}: ${event.start.dateTime} - ${event.end.dateTime}`);
});
```

## FreeBusy Query (Check Availability)

```javascript
const res = await calendar.freebusy.query({
  requestBody: {
    timeMin: '2026-01-08T00:00:00-08:00',
    timeMax: '2026-01-08T23:59:59-08:00',
    timeZone: 'America/Los_Angeles',
    items: [{ id: 'primary' }],
  },
});

const busySlots = res.data.calendars.primary.busy;
// busySlots = [{ start: '...', end: '...' }, ...]
```

## Finding Available Slots

Algorithm:
1. Get busy periods for the date range
2. Compute free periods within the requester's available window
3. Check if any free period is >= meeting duration
4. Return the earliest matching slot

# Gmail API - Sending Emails with Node.js

## Setup & Installation

```bash
npm install googleapis
```

## Authentication

```javascript
const { google } = require('googleapis');

const credentials = require('./auth/gmail/credentials.json');
const tokens = require('./auth/gmail/tokens.json');

const { client_id, client_secret } = credentials.installed;
const account = tokens.accounts[tokens.defaultAccount];

const oauth2Client = new google.auth.OAuth2(client_id, client_secret);
oauth2Client.setCredentials({
  access_token: account.access_token,
  refresh_token: account.refresh_token,
});

const gmail = google.gmail({ version: 'v1', auth: oauth2Client });
```

## Sending an Email

```javascript
function createRawEmail(to, subject, body) {
  const emailLines = [
    `To: ${to}`,
    `Subject: ${subject}`,
    'Content-Type: text/plain; charset=utf-8',
    'MIME-Version: 1.0',
    '',
    body,
  ];
  const email = emailLines.join('\r\n');
  // Base64url encode the email
  return Buffer.from(email)
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

const raw = createRawEmail('recipient@example.com', 'Meeting Confirmation', 'Hello...');

const res = await gmail.users.messages.send({
  userId: 'me',
  requestBody: { raw },
});

console.log('Message ID:', res.data.id);
// The message ID is returned in res.data.id
```

## Getting the Message ID

After sending, `res.data.id` contains the message ID which can be saved for tracking.

