const { google } = require('googleapis');
const fs = require('fs');

const credentials = JSON.parse(fs.readFileSync('/root/auth/calendar/credentials.json', 'utf8'));
const tokens = JSON.parse(fs.readFileSync('/root/auth/calendar/tokens.json', 'utf8'));

const { client_id, client_secret } = credentials.installed;
const account = tokens.accounts[tokens.defaultAccount];

const oauth2Client = new google.auth.OAuth2(client_id, client_secret);

// Set all credentials including the original scope info
oauth2Client.setCredentials({
  access_token: account.access_token,
  refresh_token: account.refresh_token,
  expiry_date: account.expiry_date,
  token_type: 'Bearer',
  scope: account.scope,
});

// Override forceRefreshOnFailure and prevent token refresh
oauth2Client.forceRefreshOnFailure = false;

// Override the refreshAccessTokenAsync to use the calendar refresh token with correct scopes
const origRefresh = oauth2Client.refreshAccessTokenAsync.bind(oauth2Client);
oauth2Client.refreshAccessTokenAsync = async function() {
  console.log('Refreshing access token with calendar scopes...');
  // Request refresh with specific scopes
  const { tokens: newTokens } = await oauth2Client.refreshToken(account.refresh_token);
  console.log('New token scopes:', newTokens.scope);
  oauth2Client.setCredentials(newTokens);
  return { credentials: newTokens };
};

const calendar = google.calendar({ version: 'v3', auth: oauth2Client });

async function main() {
  try {
    const res = await calendar.events.list({
      calendarId: 'primary',
      timeMin: '2026-01-05T00:00:00-08:00',
      timeMax: '2026-01-10T23:59:59-08:00',
      singleEvents: true,
      orderBy: 'startTime',
      timeZone: 'America/Los_Angeles',
    });

    const events = res.data.items || [];
    console.log(`Found ${events.length} events:`);
    events.forEach(event => {
      const start = event.start.dateTime || event.start.date;
      const end = event.end.dateTime || event.end.date;
      console.log(`  ${event.summary || '(no title)'}: ${start} - ${end}`);
    });
  } catch (err) {
    console.error('Error:', err.message);
    console.error('Code:', err.code);
    if (err.response) {
      console.error('Response data:', JSON.stringify(err.response.data, null, 2));
    }
  }
}

main();

