const { google } = require('googleapis');
const fs = require('fs');
const https = require('https');

const credentials = JSON.parse(fs.readFileSync('/root/auth/calendar/credentials.json', 'utf8'));
const tokens = JSON.parse(fs.readFileSync('/root/auth/calendar/tokens.json', 'utf8'));

const { client_id, client_secret, token_uri } = credentials.installed;
const account = tokens.accounts[tokens.defaultAccount];

// Refresh the token ourselves with the proper scopes
async function refreshToken() {
  const url = new URL(token_uri);
  const body = new URLSearchParams({
    client_id,
    client_secret,
    refresh_token: account.refresh_token,
    grant_type: 'refresh_token',
    scope: account.scope, // Request the calendar scopes
  });

  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: body.toString(),
  });

  const data = await response.json();
  console.log('Refresh response:', JSON.stringify(data, null, 2));
  return data;
}

async function main() {
  const tokenData = await refreshToken();
}

main();

