input.command:
# Maybe the token expiry check in the Node.js library behaves differently
# Let's check what happens when we just set the credential and let it handle it
node -e "
const { google } = require('googleapis');
const fs = require('fs');

const calCreds = JSON.parse(fs.readFileSync('/root/auth/calendar/credentials.json', 'utf8'));
const calTokens = JSON.parse(fs.readFileSync('/root/auth/calendar/tokens.json', 'utf8'));
const { client_id, client_secret } = calCreds.installed;
const account = calTokens.accounts[calTokens.defaultAccount];

const oauth2Client = new google.auth.OAuth2(client_id, client_secret);

// Set credentials
oauth2Client.setCredentials({
  access_token: account.access_token,
  refresh_token: account.refresh_token,
  expiry_date: account.expiry_date,
  scope: account.scope,
});

// The expiry_date is 9999999999999 which is year 2286
// So the library shouldn't think it's expired
console.log('Expiry date:', new Date(account.expiry_date));
console.log('Is expired?', Date.now() > account.expiry_date);

// Try to use the token
const calendar = google.calendar({ version: 'v3', auth: oauth2Client });

calendar.events.list({
  calendarId: 'primary',
  timeMin: '2026-01-05T00:00:00-08:00',
  timeMax: '2026-01-10T23:59:59-08:00',
  singleEvents: true,
  orderBy: 'startTime',
}).then(res => {
  console.log('Events:', JSON.stringify(res.data.items?.map(e => ({
    summary: e.summary,
    start: e.start?.dateTime || e.start?.date,
    end: e.end?.dateTime || e.end?.date,
  })), null, 2));
}).catch(err => {
  console.log('Error code:', err.code);
  console.log('Error message:', err.message);
  // Check if it's a 401 that triggered auto-refresh
  if (err.response) {
    console.log('Response status:', err.response.status);
    console.log('Response data:', JSON.stringify(err.response.data, null, 2));
  }
});
" 2>&1

